import json
import itertools

def solve_puzzle():
    # Houses are 1..3 from left to right
    houses = [1, 2, 3]

    # Attributes
    names = ["Peter", "Eric", "Arnold"]
    educations = ["bachelor", "associate", "high school"]
    occupations = ["teacher", "doctor", "engineer"]

    solutions = []

    for perm_names in itertools.permutations(names):
        for perm_educations in itertools.permutations(educations):
            # Constraint 3: Peter is the person with a high school diploma
            if perm_names.index("Peter") != perm_educations.index("high school"):
                continue

            for perm_occupations in itertools.permutations(occupations):
                # Helper to find indices
                idx_teacher = perm_occupations.index("teacher")
                idx_associate = perm_educations.index("associate")
                idx_eric = perm_names.index("Eric")
                idx_doctor = perm_occupations.index("doctor")
                idx_bachelor = perm_educations.index("bachelor")

                # Constraint 1: Teacher is directly left of Associate
                if not (idx_teacher + 1 == idx_associate):
                    continue

                # Constraint 2: Associate and Eric are next to each other
                if abs(idx_associate - idx_eric) != 1:
                    continue

                # Constraint 4: Doctor is the person with a bachelor's degree
                if idx_doctor != idx_bachelor:
                    continue

                # All constraints satisfied; record solution
                solutions.append((perm_names, perm_educations, perm_occupations))

    if not solutions:
        raise RuntimeError("No solution found for the given puzzle.")

    # Use the first (should be unique)
    names_sol, educations_sol, occupations_sol = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Education", "Occupation"],
            "rows": [
                [str(houses[i]), names_sol[i], educations_sol[i], occupations_sol[i]]
                for i in range(len(houses))
            ]
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False))
